inputs = ['xkaf', 'wdeyc', 'xxzwu', 'yy', 'yxzwu']
outputs = ['yxkaf', 'wdjyxyyc', 'yjyxywu', 'yy', 'yyxjyxywu']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) < len(out):
                diff_pos = len(inp)
            else:
                diff_pos = len(out)

        print(f"  First difference at position {diff_pos}")
        if diff_pos < len(out):
            print(f"  New character at pos {diff_pos}: '{out[diff_pos]}'")
        if len(out) > len(inp):
            print(f"  Length increased by {len(out) - len(inp)}")
        elif len(inp) > len(out):
            print(f"  Length decreased by {len(inp) - len(out)}")

